PARENT = ('Communication & Collaboration', '/communication-collaboration')


def svc(slug, name, **kw):
    d = dict(kind='service', slug=slug, service_name=name, card_kind='Service', card_title=name,
             eyebrow='Communication & Collaboration', trail=[PARENT, (name, '/' + slug)])
    d.update(kw)
    return d


